WITH "_src_normalized" AS (SELECT LOWER(TRIM("src"."code", '⟨U+0009⟩⟨U+000A⟩⟨U+000B⟩⟨U+000C⟩⟨U+000D⟩ ⟨U+0085⟩⟨U+00A0⟩⟨U+1680⟩⟨U+2000⟩⟨U+2001⟩⟨U+2002⟩⟨U+2003⟩⟨U+2004⟩⟨U+2005⟩⟨U+2006⟩⟨U+2007⟩⟨U+2008⟩⟨U+2009⟩⟨U+200A⟩⟨U+2028⟩⟨U+2029⟩⟨U+202F⟩⟨U+205F⟩⟨U+3000⟩')) AS "code", CASE WHEN LOWER(CASE WHEN "src"."status" IN ('N/A', '') THEN NULL ELSE "src"."status" END) = 'A' THEN 'Active' WHEN LOWER(CASE WHEN "src"."status" IN ('N/A', '') THEN NULL ELSE "src"."status" END) = 'I' THEN 'Inactive' WHEN LOWER(CASE WHEN "src"."status" IN ('N/A', '') THEN NULL ELSE "src"."status" END) = 'O''Brien' THEN 'Quoted' ELSE LOWER(CASE WHEN "src"."status" IN ('N/A', '') THEN NULL ELSE "src"."status" END) END AS "status", REGEXP_REPLACE(REGEXP_REPLACE("src"."sku", '-', '', 'g'), '([a-z]+)_([0-9]+)', '\2\1', 'g') AS "sku", TRIM("src"."city", '⟨U+0009⟩⟨U+000A⟩⟨U+000B⟩⟨U+000C⟩⟨U+000D⟩ ⟨U+0085⟩⟨U+00A0⟩⟨U+1680⟩⟨U+2000⟩⟨U+2001⟩⟨U+2002⟩⟨U+2003⟩⟨U+2004⟩⟨U+2005⟩⟨U+2006⟩⟨U+2007⟩⟨U+2008⟩⟨U+2009⟩⟨U+200A⟩⟨U+2028⟩⟨U+2029⟩⟨U+202F⟩⟨U+205F⟩⟨U+3000⟩') AS "city", LTRIM("src"."first", '⟨U+0009⟩⟨U+000A⟩⟨U+000B⟩⟨U+000C⟩⟨U+000D⟩ ⟨U+0085⟩⟨U+00A0⟩⟨U+1680⟩⟨U+2000⟩⟨U+2001⟩⟨U+2002⟩⟨U+2003⟩⟨U+2004⟩⟨U+2005⟩⟨U+2006⟩⟨U+2007⟩⟨U+2008⟩⟨U+2009⟩⟨U+200A⟩⟨U+2028⟩⟨U+2029⟩⟨U+202F⟩⟨U+205F⟩⟨U+3000⟩') AS "first", RTRIM("src"."last", '⟨U+0009⟩⟨U+000A⟩⟨U+000B⟩⟨U+000C⟩⟨U+000D⟩ ⟨U+0085⟩⟨U+00A0⟩⟨U+1680⟩⟨U+2000⟩⟨U+2001⟩⟨U+2002⟩⟨U+2003⟩⟨U+2004⟩⟨U+2005⟩⟨U+2006⟩⟨U+2007⟩⟨U+2008⟩⟨U+2009⟩⟨U+200A⟩⟨U+2028⟩⟨U+2029⟩⟨U+202F⟩⟨U+205F⟩⟨U+3000⟩') AS "last", CASE WHEN "src"."score" IN (-1) THEN NULL ELSE "src"."score" END AS "score" FROM "shop"."orders_v1" AS "src"), "_tgt_normalized" AS (SELECT LOWER(TRIM("tgt"."code", '⟨U+0009⟩⟨U+000A⟩⟨U+000B⟩⟨U+000C⟩⟨U+000D⟩ ⟨U+0085⟩⟨U+00A0⟩⟨U+1680⟩⟨U+2000⟩⟨U+2001⟩⟨U+2002⟩⟨U+2003⟩⟨U+2004⟩⟨U+2005⟩⟨U+2006⟩⟨U+2007⟩⟨U+2008⟩⟨U+2009⟩⟨U+200A⟩⟨U+2028⟩⟨U+2029⟩⟨U+202F⟩⟨U+205F⟩⟨U+3000⟩')) AS "code", LOWER(CASE WHEN "tgt"."status" IN ('N/A', '') THEN NULL ELSE "tgt"."status" END) AS "status", REGEXP_REPLACE(REGEXP_REPLACE("tgt"."sku",