tgt"."code" WHERE NOT (COALESCE("src"."status" IS NOT DISTINCT FROM "tgt"."status", FALSE) AND COALESCE("src"."sku" IS NOT DISTINCT FROM "tgt"."sku", FALSE) AND COALESCE("src"."city" IS NOT DISTINCT FROM "tgt"."city", FALSE) AND COALESCE("src"."first" IS NOT DISTINCT FROM "tgt"."first", FALSE) AND COALESCE("src"."last" IS NOT DISTINCT FROM "tgt"."last", FALSE) AND COALESCE("src"."score" IS NOT DISTINCT FROM "tgt"."score", FALSE)) ORDER BY "_veridelta_key_0" LIMIT 5
